// Shims for the cloud reference build of UnityEngine.dll from UnityCsReference.
// UnityAction delegates are generated by Unity's build (UnityEvent.tt); declare them here.
namespace UnityEngine.Events
{
    public delegate void UnityAction();
    public delegate void UnityAction<T0>(T0 arg0);
    public delegate void UnityAction<T0, T1>(T0 arg0, T1 arg1);
    public delegate void UnityAction<T0, T1, T2>(T0 arg0, T1 arg1, T2 arg2);
    public delegate void UnityAction<T0, T1, T2, T3>(T0 arg0, T1 arg1, T2 arg2, T3 arg3);
}

// Generic UnityEvent<T...> classes are generated from UnityEvent.tt at Unity build time; reference-only versions here.
namespace UnityEngine.Events
{
    using System;
    using System.Reflection;

    [Serializable]
    public class UnityEvent<T0> : UnityEventBase
    {
        public UnityEvent() {}
        public void AddListener(UnityAction<T0> call) {}
        public void RemoveListener(UnityAction<T0> call) {}
        protected override MethodInfo FindMethod_Impl(string name, Type targetObjType) => null;
        internal override BaseInvokableCall GetDelegate(object target, MethodInfo theFunction) => null;
        public void Invoke(T0 arg0) {}
    }

    [Serializable]
    public class UnityEvent<T0, T1> : UnityEventBase
    {
        public UnityEvent() {}
        public void AddListener(UnityAction<T0, T1> call) {}
        public void RemoveListener(UnityAction<T0, T1> call) {}
        protected override MethodInfo FindMethod_Impl(string name, Type targetObjType) => null;
        internal override BaseInvokableCall GetDelegate(object target, MethodInfo theFunction) => null;
        public void Invoke(T0 arg0, T1 arg1) {}
    }

    [Serializable]
    public class UnityEvent<T0, T1, T2> : UnityEventBase
    {
        public UnityEvent() {}
        public void AddListener(UnityAction<T0, T1, T2> call) {}
        public void RemoveListener(UnityAction<T0, T1, T2> call) {}
        protected override MethodInfo FindMethod_Impl(string name, Type targetObjType) => null;
        internal override BaseInvokableCall GetDelegate(object target, MethodInfo theFunction) => null;
        public void Invoke(T0 arg0, T1 arg1, T2 arg2) {}
    }

    [Serializable]
    public class UnityEvent<T0, T1, T2, T3> : UnityEventBase
    {
        public UnityEvent() {}
        public void AddListener(UnityAction<T0, T1, T2, T3> call) {}
        public void RemoveListener(UnityAction<T0, T1, T2, T3> call) {}
        protected override MethodInfo FindMethod_Impl(string name, Type targetObjType) => null;
        internal override BaseInvokableCall GetDelegate(object target, MethodInfo theFunction) => null;
        public void Invoke(T0 arg0, T1 arg1, T2 arg2, T3 arg3) {}
    }
}

namespace UnityEngine.Events
{
    using System;
    using System.Reflection;

    [Serializable]
    public class UnityEvent : UnityEventBase
    {
        public UnityEvent() {}
        public void AddListener(UnityAction call) {}
        public void RemoveListener(UnityAction call) {}
        protected override MethodInfo FindMethod_Impl(string name, Type targetObjType) => null;
        internal override BaseInvokableCall GetDelegate(object target, MethodInfo theFunction) => null;
        public void Invoke() {}
    }
}
